octo.registerCommand("frontmatter", "Add or refresh front-matter", function (t) {
  var text = String(t), body = text, existing = null;
  var m = text.match(/^---\r?\n([\s\S]*?)\r?\n---[ \t]*\r?\n?/);
  if (m) { existing = m[1]; body = text.substring(m[0].length); }
  function field(src, key) {
    if (!src) return null;
    var f = src.match(new RegExp("^" + key + ":[ \t]*(.+)$", "m"));
    return f ? f[1].replace(/^\s+|\s+$/g, "") : null;
  }
  var title = null;
  var h = body.match(/^#[ \t]+(.+)$/m);
  if (h) title = h[1].replace(/^\s+|\s+$/g, "");
  if (!title) title = field(existing, "title");
  var tags = [], seen = {}, re = /(^|\s)#([A-Za-z][A-Za-z0-9_\-]*)/g, x;
  while ((x = re.exec(body)) !== null) {
    if (!seen[x[2]]) { seen[x[2]] = true; tags.push(x[2]); }
  }
  function pad(n) { return n < 10 ? "0" + n : "" + n; }
  var d = new Date();
  var today = d.getFullYear() + "-" + pad(d.getMonth() + 1) + "-" + pad(d.getDate());
  var out = ["---"];
  if (title) out.push("title: " + title);
  out.push("created: " + (field(existing, "created") || today));
  out.push("updated: " + today);
  if (tags.length) {
    out.push("tags:");
    for (var i = 0; i < tags.length; i++) out.push("  - " + tags[i]);
  }
  out.push("---");
  return out.join("\n") + "\n" + body.replace(/^[\r\n]+/, "");
});
